// Screen S-2 (journey J-6): the comparison dashboard renders pass rates, net
// change, criterion deltas, and an evidence-backed verdict panel — every
// number sourced from the engine payload, rendered over REAL golden fixtures
// (generated by the backend engine, byte-pinned by a backend test).
import { render, screen, within } from "@testing-library/react";
import { describe, expect, it } from "vitest";

import { Dashboard } from "@/components/dashboard";
import type { Comparison } from "@/lib/api";

import insufficientJson from "./fixtures/comparison_insufficient.json";
import improvedJson from "./fixtures/comparison_improved.json";
import regressionJson from "./fixtures/comparison_regression.json";

const improved = improvedJson as unknown as Comparison;
const regression = regressionJson as unknown as Comparison;
const insufficient = insufficientJson as unknown as Comparison;

describe("Dashboard — verdict panel shows evidence (PD-V3-05)", () => {
  it("renders PROCEED with rates and signed net change from the payload only", () => {
    render(<Dashboard comparison={improved} />);
    expect(screen.getByText("PROCEED")).toBeInTheDocument();
    expect(screen.getByText("84.4%")).toBeInTheDocument(); // baseline 0.84375
    expect(screen.getByText("93.8%")).toBeInTheDocument(); // candidate 0.9375
    expect(screen.getByText("+9.4%")).toBeInTheDocument(); // net 0.09375
    expect(screen.getByText(/8 matched traces/)).toBeInTheDocument();
  });

  it("renders HOLD reasons with kind, criterion, and trace-level evidence", () => {
    render(<Dashboard comparison={regression} />);
    expect(screen.getByText("HOLD")).toBeInTheDocument();
    const panel = screen.getByRole("region", { name: /release verdict/i });
    expect(within(panel).getByText(/hard-gate regression/i)).toBeInTheDocument();
    expect(within(panel).getByText(/C-GROUNDED/)).toBeInTheDocument();
    expect(within(panel).getByText(/T-006/)).toBeInTheDocument(); // the evidence
    expect(within(panel).getByText(/guardrail violation/i)).toBeInTheDocument();
    expect(
      within(panel).getByText(/candidate pass rate 62\.5% for C-TONE is below/),
    ).toBeInTheDocument();
  });

  it("renders INSUFFICIENT_EVIDENCE as its own state with the thin-evidence reason", () => {
    render(<Dashboard comparison={insufficient} />);
    expect(screen.getByText("INSUFFICIENT_EVIDENCE")).toBeInTheDocument();
    const panel = screen.getByRole("region", { name: /release verdict/i });
    expect(within(panel).getByText(/insufficient comparable evidence/i)).toBeInTheDocument();
  });

  it("renders one criteria row per criterion with signed deltas and hard-gate marking", () => {
    render(<Dashboard comparison={regression} />);
    const table = screen.getByRole("table", { name: /criterion-level deltas/i });
    const rows = within(table).getAllByRole("row");
    expect(rows).toHaveLength(1 + regression.criteria.length); // header + 4
    const grounded = within(table).getByText("C-GROUNDED").closest("tr");
    expect(grounded).not.toBeNull();
    expect(within(grounded as HTMLElement).getByText(/hard gate/i)).toBeInTheDocument();
    expect(within(grounded as HTMLElement).getByText("-12.5%")).toBeInTheDocument();
    const tone = within(table).getByText("C-TONE").closest("tr") as HTMLElement;
    expect(within(tone).getByText("-25.0%")).toBeInTheDocument();
    const accuracy = within(table).getByText("C-ACCURACY").closest("tr") as HTMLElement;
    expect(within(accuracy).getByText("+12.5%")).toBeInTheDocument();
  });

  it("shows the input digests — the verdict's evidence provenance", () => {
    render(<Dashboard comparison={regression} />);
    expect(screen.getByText(regression.baseline_digest)).toBeInTheDocument();
    expect(screen.getByText(regression.candidate_digest)).toBeInTheDocument();
  });

  it("renders hostile payload strings as text, never markup", () => {
    const hostile = {
      ...regression,
      criteria: [
        {
          ...regression.criteria[0],
          description: '<script>window.pwned=true</script>',
        },
      ],
    } as Comparison;
    render(<Dashboard comparison={hostile} />);
    expect(screen.getByText(/<script>window\.pwned=true<\/script>/)).toBeInTheDocument();
    expect(document.querySelector("script")).toBeNull();
    expect((window as unknown as { pwned?: boolean }).pwned).toBeUndefined();
  });
});
